#include <algorithm>
#include <iostream>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long lim, bal = 0, low = 0;
    cin >> n >> lim;
    for (int i = 1; i <= n; i++) {
        string k;
        cin >> k;
        if (k == "D") {
            long long x;
            cin >> x;
            bal += x;
        } else if (k == "W") {
            long long x;
            cin >> x;
            if (bal - x < -lim) cout << "REJECT " << i << '\n';
            else bal -= x;
        } else if (bal < 0) {
            bal -= 1;
        }
        low = min(low, bal);
    }
    cout << "BALANCE " << bal << "\nMIN " << low << '\n';
    return 0;
}

